/**
 * Panzer Dragoon Orta - recompiled game entry point (template: xboxrecomp templates/game).
 *
 * Fill in from docs/xbe.md (tools\m0_analyze.ps1): entry point, XDK builds, title ID.
 * Workflow and pitfalls: toolkit docs/porting_guide.md, docs/lessons_learned.md.
 * OS-specific parts (log, crash handler, paths) live in platform/.
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#include "kernel.h"
#include "port_icon.h"          /* g_port_icon_bmp: assets/icon_64.bmp, generated by CMake */
#include "xbox_memory_layout.h"
#include "xbox_settings.h"
#include "apu.h"
#include "apu_gp.h"
#include "xinput_xbox.h"
#include "xinput_bind.h"

#include "platform/host.h"
#include "platform/host_info.h"     /* toolkit: the log's version + host lines */
#include "settings.h"
#include <string.h>
#include "input.h"
#if defined(ORTA_VULKAN)
#include "nv2a_vk.h"
#include "vk_check.h"
#include <SDL3/SDL.h>
#endif
#if defined(ORTA_INSTALLER)
#include <string.h>
#include "game_setup.h"
#include "game_setup_ui.h"
#endif

#define GAME_ENTRY_POINT 0x00232A9Bu   /* XBE entry point, PAL (docs/xbe.md) */

#if defined(ORTA_INSTALLER)
/* First start (M5, CLAUDE.md "Portable install layout"; model THPS 2X thps_game_setup): game/ holds the extracted
 * disc or one disc image (XISO or full redump); an image is extracted into game/, every file checked, then deleted
 * (toolkit game_setup.h). Touches only game/. Version rules: a wrong title ID or an unsupported default.xbe stops
 * the start with the toolkit's message, for an image and an extracted folder alike. RECOMP_NO_DIALOGS=1: log only.
 * RECOMP_SETUP_TEST_FREE_MB=<n>: tests only, pretend the drive has n MB free. Returns 0 when the game cannot start. */
static void setup_log(void *ctx, const char *text)
{
    (void)ctx;
    printf("[SETUP] %s\n", text);
    fflush(stdout);
}

static int orta_game_setup(const char *game_dir)
{
    /* The supported versions (CLAUDE.md title decisions, docs/xbe.md, README): name + default.xbe SHA-1. PAL only
     * (maintainer 2026-11-01; the US variant is on hold). */
    static const xr_game_version versions[] = {
        { "Europe", "57213FF35A19807DEF664F9018CC2923815DFA1F" },
    };
    const char *fm = getenv("RECOMP_SETUP_TEST_FREE_MB");
    int quiet = xr_no_dialogs();
    xr_game_setup_opts o;
    xr_game_setup_result r;
    XrSetupUi *ui = xr_setup_ui_open("Panzer Dragoon Orta Recomp");
    int rc;

    memset(&o, 0, sizeof o);
    if (fm && *fm)
        o.test_free_bytes = (uint64_t)strtoull(fm, NULL, 10) << 20;
    o.game_dir = game_dir;
    o.game = "Panzer Dragoon Orta";
    o.title_id = 0x4947002Bu;
    o.versions = versions;
    o.version_count = sizeof versions / sizeof versions[0];
    o.log = setup_log;
    if (ui) {                           /* the progress window opens only for an install */
        o.ctx = ui;
        o.progress = xr_setup_ui_progress;
        o.cancelled = xr_setup_ui_cancelled;
    }
    rc = xr_game_setup(&o, &r);
    printf("[SETUP] %s: %s\n", xr_game_setup_code_name(rc), r.message);
    if (rc != XR_SETUP_READY && rc != XR_SETUP_INSTALLED) {
        if (!quiet)
            xr_setup_ui_message(ui, 1, r.message);
        xr_setup_ui_close(ui);
        return 0;
    }
    xr_setup_ui_close(ui);
    return 1;
}
#endif

extern ptrdiff_t g_xbox_mem_offset;
extern void xbox_OhciInit(void);
extern void xbe_entry_point(RECOMP_PARAMS);       /* generated */
extern int recomp_dispatch_init(void);   /* generated */

/* The main thread's guest register set (option C): the title's first thread
 * runs on it. Static, so the watchdog and crash handler can still read it. */
static X86Ctx s_main_ctx = X86CTX_INIT;

#ifdef __ANDROID__
/* Android: the game is a library built on the phone (libORTA_game.so); the APK's libmain.so (packaging/android,
 * loader.c) dlopen()s it after the first-start build and calls this */
#define main orta_game_main
int orta_game_main(int argc, char **argv);
#endif
int main(int argc, char **argv)
{
    X86Ctx *ctx = &s_main_ctx;
    HostOptions opt;
    char xbe_path[HOST_PATH_MAX];
    void *xbe;
    size_t xbe_size = 0;

    if (host_init(argc, argv, &opt) != 0)
        return 1;
    printf("=== Panzer Dragoon Orta - static recompilation ===\n");
    settings_init(opt.save_dir);                   /* saves\settings.ini: RECOMP OPTIONS values (settings.h) */
    host_log_version_and_host(opt.game_dir);       /* "version: ..." / "host: ..." for bug reports */
    /* RECOMP OPTIONS > FRAME RATE > VSYNC (vsync=on|off): the toolkit reads RECOMP_VSYNC once at start, so the
     * saved value becomes its default here (an explicit RECOMP_VSYNC still wins); a change needs a restart. */
    if (!strcmp(settings_get("vsync", "on"), "off"))
        host_setenv_default("RECOMP_VSYNC", "0");
    /* RECOMP OPTIONS > FRAME RATE > FRAME PACING (frame_pacing=display|timer; port guideline 2026-11-05, THPS 2X
     * v1.1.0): DISPLAY (default) = the guest vblank follows a 120 / 180 / 240 Hz display's own vblank (toolkit
     * host_vblank); 60 HZ TIMER = the old clock. Read once by the kernel at start. */
    if (!strcmp(settings_get("frame_pacing", "display"), "timer"))
        host_setenv_default("RECOMP_FRAME_PACING", "timer");
    /* FRAME RATE 120 (night order 2026-11-07): the guest vblank at 120 Hz (toolkit RECOMP_GUEST_HZ); the game's
     * frame time step goes to 1/120 in orta_options_apply. ORTA_FPS=120 / 60 forces it for one run. */
    {
        const char *e = getenv("ORTA_FPS");
        /* the saved value is ignored for now: 120 is not decoupled yet (recomp_manual.c RV_FRAMERATE), only ORTA_FPS */
        int fps120 = e && *e && atoi(e) == 120;
        if (fps120)
            host_setenv_default("RECOMP_GUEST_HZ", "120");
    }
    /* SOUND > SPEAKERS (speakers=stereo|5.1; night order 2026-11-07, maintainer: only the game's own 5.1, a line in
     * the game's SOUND options): 5.1 asks the toolkit for six channels (RECOMP_AUDIO_51); it is granted only on a
     * device with 5.1 speakers, and then XC_AUDIO tells Orta it runs on a Dolby Digital Xbox - Orta mixes its
     * sounds across the six speakers itself (FC dialogue, surrounds at front level; run 20261108_005443_spk_10000).
     * Read at start: a change asks RESTART NEEDED. */
    if (!strcmp(settings_get("speakers", "stereo"), "5.1"))
        host_setenv_default("RECOMP_AUDIO_51", "1");
    /* The renderer's per-frame ring at 16 MB instead of 48 (two in flight, both resident): Orta's peak is 8 MB per
     * frame (RECOMP_VK_RING_STATS through boot, movies, menus and 6 min of episode 1: 0 mid-frame flushes) - 64 MB
     * less working set (maintainer 2026-11-08: RAM in menus / movies; working set of the title 356 -> 291 MB). */
    host_setenv_default("RECOMP_VK_RING_MB", "16");

    /* Before xbox_MemoryLayoutInit, which reads them (run 20261101_122728_m1_apu: set after it, the APU stayed
     * untrapped and DirectSoundCreate still said DSERR_NODRIVER). Audio LLE - see the APU block below. */
    host_setenv_default("RECOMP_AC97_READY", "1");
    host_setenv_default("RECOMP_APU_DSP_ACK", "auto");
    /* D3D's busy KEVENT is built by hand (no KeInitializeEvent); give it a real host event (as Burnout 3 and
     * the reference port). */
    host_setenv_default("RECOMP_TITLE_KEVENTS", "1");
    /* File-I/O completion APCs at the issuing thread's next alertable wait, as on NT (toolkit 1545a76, opt-in):
     * Orta's CRI file layer clears its done flag after ReadFileEx/WriteFileEx return and then waits for the
     * completion - inline delivery loses it and the game hangs after START at the title. */
    host_setenv_default("RECOMP_APC_DEFERRED", "1");
    /* Real guest vblank interrupts (the title's ISR/DPC retires flips, as Burnout 3). Every dev run had it from
     * tools\run.ps1; the first play.ps1 session without it hung at boot (no "vblank -> ISR" line, a loader thread
     * spinning in NtWaitForSingleObjectEx, 2026-11-01 21:35) - so it is the exe's default, not a run-script value. */
    host_setenv_default("RECOMP_VBLANK", "1");
    /* Window crop OFF (maintainer, 2026-11-01): Orta draws its own cinematic bars whose height changes per scene
     * (13.8 / 8.8 / 7.9 / 3.3 % top+bottom, run 20261101_215110_replay_43), so the crop resized the window again and
     * again; the PAL side bars it was meant for are gone with AV region NTSC-M. The game's bars stay, as on the
     * console. */
    host_setenv_default("RECOMP_VK_WINDOW_CROP", "0");
    /* the port's window / taskbar icon (assets/icon_64.bmp -> port_icon.h), before the first window (installer) */
    xbox_set_window_icon(g_port_icon_bmp, sizeof g_port_icon_bmp);

#if defined(ORTA_VULKAN)
    /* No Vulkan 1.3 device: a polite message box and out, before the installer or a window (maintainer
     * 2026-11-04; the launcher asks the same, src/vk_check.c). The toolkit's own device check stays behind it as
     * the last line. Headless runs (RECOMP_VK_HEADLESS=1) skip it; RECOMP_NO_DIALOGS=1 logs only. */
    {
        const char *hl = getenv("RECOMP_VK_HEADLESS"), *nd = getenv("RECOMP_NO_DIALOGS");
        char found[1024], msg[1600];
        if (!(hl && *hl == '1') && !orta_vk_check(found, sizeof found)) {
            orta_vk_message(msg, sizeof msg, found);
            fprintf(stderr, "[VK] no Vulkan 1.3 device: %s\n", found);
            if (!(nd && *nd == '1'))
                SDL_ShowSimpleMessageBox(SDL_MESSAGEBOX_ERROR, "Panzer Dragoon Orta Recomp", msg, NULL);
            return 1;
        }
        if (!(hl && *hl == '1'))
            printf("[VK] devices: %s\n", found);
    }
#endif

#if defined(ORTA_INSTALLER)
    if (!orta_game_setup(opt.game_dir))
        return 1;
#endif
    snprintf(xbe_path, sizeof(xbe_path), "%s/default.xbe", opt.game_dir);
    xbe = host_read_file(xbe_path, &xbe_size);
    if (!xbe) {
        host_fatal("Cannot read game/default.xbe - put the game's disc image (.iso) or its extracted files into "
                   "the game folder.");
        return 1;
    }
    /* 128 MB of guest RAM (the debug kit's size; toolkit XBOX_DEVKIT_RAM) instead of 64: the guest heap ran out at
     * the end of episode 3 - the closing cut scene asks for 10 MB, the heap's high mark stood at 45.7 of 48.5 MB
     * ("xbox_HeapAlloc: out of memory (requested 10058688 ...)", then a NULL read at 0x000690F6 and a hang; known
     * issue #10, play-through 2026-11-08). The heap top follows RAM: ~112 MB. RECOMP_RAM_MB=64 for the old size. */
    {
        const char *e = getenv("RECOMP_RAM_MB");
        int mb = e && *e ? atoi(e) : 128;
        if (mb == 64 || mb == 128) {
            xbox_SetTotalRam((size_t)mb * 1024u * 1024u);
            printf("guest RAM %d MB\n", mb);
        }
    }
    if (!xbox_MemoryLayoutInit(xbe, xbe_size)) {    /* also sets g_xbox_title_id */
        host_fatal("Failed to map the Xbox memory layout.");
        return 1;
    }
    g_xbox_mem_offset = xbox_GetMemoryOffset();
    host_debug_start();

#if defined(ORTA_VULKAN)
    host_setenv_default("RECOMP_PB_EXEC", "1");     /* pushbuffer executor -> nv2a_vk */
    /* Inline / immediate vertices in fixed-function mode are transformed like the hardware does (toolkit switch,
     * Burnout 3 needs it too). Orta sends its lasers, explosions, hit glows, lock-on rings and the aim cursor as
     * inline vertices with WORLD positions (run 20261103_B_lines: green laser line list a0 = -25/-1.3/1058);
     * the toolkit default takes inline vertices as pre-transformed (2D quads), so they all landed at pixel (-25,-1)
     * - the flicker in the top-left corner the maintainer saw. Verified: run 20261103_185727_B_inlffp (light-dragon
     * replay) shows explosions, laser glows, lock-on rings and the aim cursor. */
    host_setenv_default("RECOMP_INLINE_FFP", "1");
#endif
    /* Pad scripts and the recorder count Orta's own frame counter for their "f" base (toolkit 59c5dd7): the
     * engine's +1-per-game-frame word at 0x004A6FF0 (sub_0028E800; 59.70/s against 59.94 vblanks/s, it stands
     * still in hitches - 0x003427F8 resets per scene). Replays in guest vblanks drifted until the dragon died
     * (runs 20261103_201854 / _204742). */
    host_setenv_default("RECOMP_PAD_GAME_FRAME", "4A6FF0");
    /* Input: the title's XPP driver on the OHCI model (LLE fallback). Check the
     * controller-port mapping of this XDK build (lessons_learned.md). */
    host_setenv_default("RECOMP_USB", "1");
    host_setenv_default("RECOMP_KEYBOARD", "1");

    /* Audio, M1: the title's own DSOUND on the emulated MCPX APU (LLE), as Burnout 3. Orta's start-up needs a
     * working DirectSoundCreate: sub_0003D200 -> sub_0021EE10 returned DSERR_NODRIVER (0x88780078, run
     * 20261101_121408_m1_trace) and main() quit to the dashboard. DirectSound waits for the AC'97 codec
     * (RECOMP_AC97_READY) and for the DSP to clear its command doorbell (RECOMP_APU_DSP_ACK=auto finds it).
     * The toolkit's HLE DirectSound (xdk_dsound.h) has no 3D / mix bins / effects image yet; Orta loads
     * dsstdfx.bin - HLE is an M3 decision. The variables are set at the top of main (xbox_MemoryLayoutInit
     * reads RECOMP_AC97_READY to trap the APU registers); here the APU model itself comes up. */
    {
        typedef struct MCPXAPUState MCPXAPUState;
        extern MCPXAPUState *mcpx_apu_init_standalone(uint8_t *ram_ptr);
        extern MCPXAPUState *g_apu_state;

        /* Mix bins as Orta's dsstdfx image wires them (toolkit aa5632b; model Burnout 3 main.c): the
         * fallback summed every bin at full level, so the 3D effects (bins 6/7 + a copy in bin 10) came out ~9 dB
         * too loud and drowned the music (bins 0/1) - maintainer's play test 2026-11-01, GP dump run
         * 20261102_001501_trace_49b. RECOMP_APU_GP=0 keeps the old mixdown for an A/B. */
        {
            const char *gp = getenv("RECOMP_APU_GP");
            if (!(gp && *gp == '0'))
                apu_gp_wire_xdk_std();
        }
        g_apu_state = mcpx_apu_init_standalone((uint8_t *)(uintptr_t)xbox_GetMemoryOffset());
        printf("MCPX APU: %s\n", g_apu_state ? "initialised" : "FAILED");
    }
    {
        extern void orta_apu_diag_start(void);   /* dev: ORTA_APU_DIAG=<ms> (src/platform/apu_diag_win32.c) */
        orta_apu_diag_start();
    }
    {
        extern void orta_cri_lock_init(void);    /* recomp_manual.c: CRI server pass vs. destroy, ORTA_CRI_LOCK=0 off */
        orta_cri_lock_init();
    }
    game_input_init();
    /* Button bindings per device (toolkit xinput_bind.h; RECOMP OPTIONS: CONTROLS > BUTTON MAPPING): kept in
     * saves\settings.ini (bind.keyboard, bind.pad.<GUID>), forced with ORTA_BIND_KEYBOARD / ORTA_BIND_PAD_<GUID> /
     * ORTA_BIND_PAD, ORTA_BIND_RESET=1 ignores the stored ones (emergency exit). Model: THPS 2X main.c. */
    xbox_InputBindSetStore(settings_get, settings_set, "ORTA_BIND");
    /* The USB controller model. 2026-11-05 it sat below the boot animation for a while: the toolkit's OHCI thread
     * gave up when the title's driver had not started the controller within 6 s, and media\boot.mpg plays 11.6 s
     * (maintainer's session 2026-11-05 02:42; run 20261105_025018_bootusb1). The toolkit waits on now (toolkit
     * 260af9e), so it is back in its place. */
    if (*getenv("RECOMP_USB") != '0')
        xbox_OhciInit();

    /* The PAL disc's console settings (toolkit xbox_settings.h). Without a game region XAPI's start-up check
     * quick-rebooted at once (run 20261101_114630_m1_sem: HalReturnToFirmware(2) from sub_0022DA5C, launch
     * page type 0xFFFFFFFF, own title ID). Rest of the world, DVD region 2, CET. Languages: the text
     * files on the disc (EN/FR/GE/IT/SP; JP files exist too - check in M3 whether the game offers it).
     * AV region NTSC-M (maintainer decision 2026-11-01, standard for every recomp): with PAL-I (+PAL60) Orta
     * draws only 580 of 640 columns (30 px black left/right - its PAL TV layout); with NTSC-M the full width
     * at 60 Hz. Verified both ways: our port (run 20261101_144011_m2_ntsc2 vs earlier PAL runs) and xemu with
     * the maintainer's EEPROM (his NTSC-M original: full width; a PAL-I copy: the same side bars). */
    {
        XboxSettings pal = {
            XBOX_LANG_ENGLISH,
            XBOX_LANG_BIT(XBOX_LANG_ENGLISH) | XBOX_LANG_BIT(XBOX_LANG_GERMAN) | XBOX_LANG_BIT(XBOX_LANG_FRENCH) |
                XBOX_LANG_BIT(XBOX_LANG_SPANISH) | XBOX_LANG_BIT(XBOX_LANG_ITALIAN),
            0, XBOX_AV_REGION_NTSC_M, XBOX_GAME_REGION_ROW, 2, -60, 0};
        /* ASPECT RATIO (saves\settings.ini aspect_ratio=4:3|16:9, ORTA_ASPECT_RATIO overrides one run): 16:9 is
         * the console's widescreen setting (XC_VIDEO 0x00010000) - Orta's own native 16:9 for everything
         * (maintainer 2026-11-01: "direkt in die recomp optionen setzen und spiel funktionen nutzen"; toolkit
         * 8d47326 AV caps + b5105ee 16:9 window). Read at start only: Orta creates its device once, so a change
         * in RECOMP OPTIONS needs RESTART NOW. RECOMP_XBOX_VIDEO still overrides it (toolkit). */
        /* 16:10 / 21:9 (night order 2026-11-07): Orta's own 16:9 path as well, widened further by the port
         * (recomp_manual.c orta_aspect_*: the game's 4/3 widescreen factor becomes aspect / (4/3)); the toolkit's
         * window / present take the value from RECOMP_WIDESCREEN (option-c xbox_video_aspect). */
        {
            const char *ar = settings_get("aspect_ratio", "4:3");
            if (strcmp(ar, "4:3") != 0)
                pal.video |= 0x00010000u;
            if (!strcmp(ar, "16:10") || !strcmp(ar, "21:9"))
                host_setenv_default("RECOMP_WIDESCREEN", ar);
        }
        /* LANGUAGE (RECOMP OPTIONS, saves\settings.ini language=system|english|german|french|spanish|italian): the
         * console language XAPI reports; Orta picks its text files from it at start, so a change needs a restart.
         * system (default) = the toolkit's choice: the host UI language when the disc has it, else English. An
         * explicit language clears the disc's language set, so the toolkit takes `language` as it is. */
        {
            const char *lang = settings_get("language", "system");
            uint32_t l = !strcmp(lang, "english") ? XBOX_LANG_ENGLISH : !strcmp(lang, "german") ? XBOX_LANG_GERMAN
                       : !strcmp(lang, "french") ? XBOX_LANG_FRENCH : !strcmp(lang, "spanish") ? XBOX_LANG_SPANISH
                       : !strcmp(lang, "italian") ? XBOX_LANG_ITALIAN
                       : !strcmp(lang, "japanese") ? XBOX_LANG_JAPANESE : 0;   /* recomp_manual.c sub_0002A970 */
            if (l) { pal.language = l; pal.languages = 0; }
        }
        xbox_settings_set_port(&pal);
        /* The language the game really gets (maintainer 2026-11-07: log it, it can matter for bug reports): the
         * [OPT] line only shows the setting (system = host UI language if the disc has it, else English), and
         * RECOMP_XBOX_LANGUAGE overrides both - this is the resolved XC_LANGUAGE value. */
        {
            static const char *const k_lang[] = { "?", "english", "japanese", "german", "french", "spanish",
                                                  "italian", "korean", "chinese", "portuguese" };
            uint32_t r = xbox_settings()->language;
            fprintf(stderr, "[ORTA] language: setting %s -> %s (XC_LANGUAGE %u)\n", settings_get("language", "system"),
                    r < sizeof k_lang / sizeof *k_lang ? k_lang[r] : "?", r);
        }
    }
    xbox_kernel_init();
    {
        /* Storage layout (docs/storage.md). Decide TDATA after looking at what the
         * title writes there; default: saves. */
        XboxPathConfig cfg;
        xbox_path_config_default(&cfg);
        cfg.game_dir = opt.game_dir;
        cfg.save_dir = opt.save_dir;
        cfg.data_dir = opt.data_dir;
        cfg.tdata = XBOX_TDATA_SAVES;
        xbox_path_init_cfg(&cfg);
    }
    xbox_kernel_bridge_init();
#if defined(ORTA_VULKAN)
    nv2a_vk_set_key_handler(xbox_InputKeyEvent);
    nv2a_vk_set_quit_handler(host_quit);
    nv2a_vk_install();
    {
        extern void orta_options_apply(void);    /* recomp_manual.c: saved RECOMP OPTIONS values into the renderer */
        orta_options_apply();
    }
    {
        /* The boot animation media\boot.mpg (BOOT ANIMATION on, the default), before the title starts; media\ sits
         * next to game\ (CLAUDE.md install layout). Model: THPS 2X main.c. */
        extern char g_orta_media_dir[512];
        extern void orta_boot_video(void);
        size_t n = strlen(opt.game_dir);
        while (n && (opt.game_dir[n - 1] == '/' || opt.game_dir[n - 1] == '\\'))
            n--;
        while (n && opt.game_dir[n - 1] != '/' && opt.game_dir[n - 1] != '\\')
            n--;
        snprintf(g_orta_media_dir, sizeof g_orta_media_dir, "%.*smedia", (int)n, opt.game_dir);
        if (getenv("ORTA_MEDIA_DIR") && *getenv("ORTA_MEDIA_DIR"))   /* dev / tests: another media folder */
            snprintf(g_orta_media_dir, sizeof g_orta_media_dir, "%s", getenv("ORTA_MEDIA_DIR"));
        orta_boot_video();
    }
    /* TODO (M2): wrap the title's D3D fence wait in recomp_manual.c and register
     * its GPU semaphore (porting_guide.md, M2). */
#endif
    g_esp = XBOX_STACK_TOP;
    xbox_diag_ctx_set(ctx);   /* the crash handler and watchdog read this set */
    if (!recomp_dispatch_init())
        fprintf(stderr, "[BOOT] flat dispatch unavailable\n");
    xbox_WatchdogStart();

    printf("Entry point 0x%08X - starting game\n", GAME_ENTRY_POINT);
    fflush(stdout);
    RECOMP_CALL_GUEST(xbe_entry_point);

    xbox_kernel_shutdown();
    xbox_MemoryLayoutShutdown();
    free(xbe);
    return 0;
}
